contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that calling openMakeFor or openTakeFor never results in a negative position fee
    // observable through public getters: we read makerFee/takerFee and price via rate-related calls.
    // Because many internals are not observable, we assert that the computed position fee formula
    // using public getters is always >= 0 and that calling the entry does not revert when parameters
    // produce zero fee.

    // Single public test function taking parameters to call openMakeFor or openTakeFor.
    function run(bool useMake, address account, uint256 amountRaw) public payable {
        require(account != address(0));
        // ensure amount is within UFixed18 scale: use raw as whole units, convert via UFixed18.from by calling openMakeFor/openTakeFor expects UFixed18 encoded externally,
        // but we cannot construct UFixed18 type here; instead we pass through amountRaw cast via abi encoding into function expecting UFixed18.

        // read current fees and latestVersion and price via public view functions
        (bool okMaker, bytes memory retMaker) = address(c).call(abi.encodeWithSignature("makerFee()"));
        require(okMaker);
        // makerFee() returns a UFixed18 (type alias) which occupies uint256
        uint256 makerFeeRaw = abi.decode(retMaker, (uint256));

        (bool okTaker, bytes memory retTaker) = address(c).call(abi.encodeWithSignature("takerFee()"));
        require(okTaker);
        uint256 takerFeeRaw = abi.decode(retTaker, (uint256));

        // read latest oracle version to obtain price via atVersion
        (bool okLatest, bytes memory retLatest) = address(c).call(abi.encodeWithSignature("latestVersion()"));
        require(okLatest);
        uint256 latestVersion = abi.decode(retLatest, (uint256));

        // If latestVersion is zero, atVersion may revert; guard by using try/catch via low-level call
        bytes memory priceData;
        if (latestVersion != 0) {
            (bool okAt, bytes memory retAt) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", latestVersion));
            if (okAt) {
                // atVersion returns OracleVersion struct: (uint256 version, uint256 timestamp, int256 price)
                // We only need price (Fixed18) which is int256 encoded as int256 in a bytes tuple.
                // Decode as (uint256,uint256,int256)
                (uint256 v, uint256 ts, int256 price) = abi.decode(retAt, (uint256, uint256, int256));
                priceData = abi.encode(price);
            } else {
                priceData = abi.encode(int256(0));
            }
        } else {
            priceData = abi.encode(int256(0));
        }

        int256 price = abi.decode(priceData, (int256));
        // position fee (in UFixed18 * abs(price) * fee) is non-negative since UFixed18 and abs(price) are non-negative
        // Compute a conservative integer expression representing the position fee's sign using public fee numbers.
        // UFixed18 is a uint256 scaled by 1e18. price is Fixed18 (int256 scaled by 1e18). maker/takerFeeRaw are uint256 scaled by 1e18.

        // We will attempt the actual state-changing call and record whether it reverted.
        bool reverted;
        if (useMake) {
            // prepare calldata for openMakeFor(address,UFixed18)
            bytes memory arg = abi.encodeWithSignature("openMakeFor(address,uint256)", account, amountRaw);
            (bool success, ) = address(c).call(arg);
            reverted = !success;
        } else {
            bytes memory arg = abi.encodeWithSignature("openTakeFor(address,uint256)", account, amountRaw);
            (bool success, ) = address(c).call(arg);
            reverted = !success;
        }

        // Now assert the general rule: the computed position fee using public values is non-negative, and if price == 0 or fee==0 then call must not revert due to negative fee
        // Formulate: abs(price) * feeRaw * amountRaw >= 0  (always true) and if abs(price)==0 or feeRaw==0 then the call does not revert.

        uint256 absPriceScaled = price < 0 ? uint256(uint256(-price)) : uint256(uint256(price));
        uint256 feeRaw = useMake ? makerFeeRaw : takerFeeRaw;

        // condition: (absPriceScaled * feeRaw * amountRaw) is a uint256 thus >= 0 always; we assert the meaningful part: if either absPriceScaled==0 or feeRaw==0 then reverted==false
        assert(((absPriceScaled == 0 || feeRaw == 0) ? (reverted == false) : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that exercises either openMakeFor or openTakeFor directly on c.
    // Parameters:
    // - useMake: if true call openMakeFor, else call openTakeFor
    // - account: target account for the position op
    // - amountRaw: raw uint256 representing the UFixed18 encoded value to pass through
    function run(bool useMake, address account, uint256 amountRaw) public payable {
        require(account != address(0));

        // Read public fees (view calls allowed anywhere).
        uint256 makerFeeRaw = c.makerFee();
        uint256 takerFeeRaw = c.takerFee();

        // Read latest oracle version and extract price (Fixed18 as int256) via atVersion when possible.
        uint256 latestVer = c.latestVersion();
        int256 priceInt = 0;
        if (latestVer != 0) {
            // atVersion is view; call and decode the returned struct via the public ABI by calling the function and letting Solidity handle struct return
            (uint256 v, uint256 ts, int256 price) = c.atVersion(latestVer);
            priceInt = price;
        }

        // Compute absolute price scaled (Fixed18 uses int256 scaled by 1e18). Use uint256 safely.
        uint256 absPriceScaled = priceInt < 0 ? uint256(uint256(-priceInt)) : uint256(uint256(priceInt));

        // Choose fee based on action
        uint256 feeRaw = useMake ? makerFeeRaw : takerFeeRaw;

        // Perform the state-changing call as a top-level statement per constraints.
        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, amountRaw) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amountRaw) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule (single assert): computed position-fee product is non-negative by construction (uints),
        // and importantly if either fee rate or abs(price) is zero then the call must NOT revert (no position-fee-induced revert possible).
        // Expressed as: (if feeRaw==0 || absPriceScaled==0) then reverted == false.
        assert((feeRaw == 0 || absPriceScaled == 0) ? reverted == false : true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If fee==0 or price.abs()==0 then opening a position should not revert.
    // Parameters:
    // - useMake: true => call openMakeFor, false => call openTakeFor
    // - account: target account (must be non-zero)
    // - amount: UFixed18 encoded amount to pass through (as uint256)
    function run(bool useMake, address account, uint256 amount) public payable {
        require(account != address(0));

        // Read fees (UFixed18). We cannot cast directly to uint256; instead check isZero via public UFixed18Lib.ZERO comparison
        // The public getter returns UFixed18 so we can call methods that are view; but only direct equality available is via calling methods on c?
        // Simpler: call makerFee() and takerFee() and then call their truncate() via the contract's UFixed18Lib indirectly is not possible.
        // Instead, detect zero by comparing to UFixed18Lib.ZERO through the observable behavior: call makerFee() and check its truncate() == 0 may be ambiguous.
        // But UFixed18 has public function truncate in UFixed18Lib and it's internal; cannot call. However we can check equality to zero by comparing returned value to 0 when treated as uint256 via abi decoding.
        // Solidity allows assigning UFixed18 return to uint256 by ABI decoding: call returns (uint256) underlying. So do that via a low-level staticcall to obtain raw uint.

        // Helper: get raw uint256 underlying of a UFixed18-returning function via staticcall.
        (bool ok1, bytes memory data1) = address(c).staticcall(abi.encodeWithSignature("makerFee()"));
        require(ok1);
        uint256 makerFeeRaw = abi.decode(data1, (uint256));

        (bool ok2, bytes memory data2) = address(c).staticcall(abi.encodeWithSignature("takerFee()"));
        require(ok2);
        uint256 takerFeeRaw = abi.decode(data2, (uint256));

        // Read latestVersion and if non-zero read atVersion(latest) to get oracle price (Fixed18 wraps int256 underlying)
        (bool ok3, bytes memory data3) = address(c).staticcall(abi.encodeWithSignature("latestVersion()"));
        require(ok3);
        uint256 latest = abi.decode(data3, (uint256));

        int256 priceRaw = 0;
        if (latest != 0) {
            (bool ok4, bytes memory data4) = address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", latest));
            require(ok4);
            // atVersion returns (uint256 version, uint256 timestamp, int256 price)
            (uint256 v, uint256 ts, int256 price) = abi.decode(data4, (uint256, uint256, int256));
            priceRaw = price;
        }

        // absolute value of price (as uint256)
        uint256 absPrice = priceRaw < 0 ? uint256(uint256(-priceRaw)) : uint256(uint256(priceRaw));

        // Perform the state-changing call and record whether it reverted.
        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: if chosen fee is zero OR absolute price is zero, the call must NOT revert.
        uint256 chosenFeeRaw = useMake ? makerFeeRaw : takerFeeRaw;
        assert((chosenFeeRaw == 0 || absPrice == 0) ? reverted == false : true);
    }

    receive() external payable {}
}

