    // If fee==0 or price.abs()==0 then opening a position should not revert.
    // Parameters:
    // - useMake: true => call openMakeFor, false => call openTakeFor
    // - account: target account (must be non-zero)
    // - amount: raw uint256 to be passed as UFixed18 (ABI-compatible)
    function run(bool useMake, address account, uint256 amount) public payable {
        require(account != address(0));

        // Read makerFee() and takerFee() via external view calls
        (bool ok1, bytes memory d1) = address(c).staticcall(abi.encodeWithSignature("makerFee()"));
        require(ok1);
        uint256 makerFeeRaw = abi.decode(d1, (uint256));

        (bool ok2, bytes memory d2) = address(c).staticcall(abi.encodeWithSignature("takerFee()"));
        require(ok2);
        uint256 takerFeeRaw = abi.decode(d2, (uint256));

        // Determine absolute oracle price magnitude at latestVersion if available
        uint256 absPrice = 0;
        (bool ok3, bytes memory d3) = address(c).staticcall(abi.encodeWithSignature("latestVersion()"));
        require(ok3);
        uint256 latest = abi.decode(d3, (uint256));
        if (latest != 0) {
            // atVersion(uint256) returns (uint256,uint256,int256) per interface
            (bool ok4, bytes memory d4) = address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", latest));
            require(ok4);
            (uint256 v, uint256 ts, int256 price) = abi.decode(d4, (uint256, uint256, int256));
            // compute absolute value as uint256
            if (price < 0) {
                // avoid overflow when price == type(int256).min, but absolute magnitude then fits in uint256
                absPrice = uint256(uint256(-price));
            } else {
                absPrice = uint256(uint256(price));
