                reverted = true;
            }
        }

        uint256 chosenFeeRaw = useMake ? makerFeeRaw : takerFeeRaw;
        // General rule: if chosen fee is zero OR absolute price is zero, the call must NOT revert.
        assert((chosenFeeRaw == 0 || absPrice == 0) ? reverted == false : true);
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address multiInvoker;

    constructor(C _c) {
        c = _c;
        // multiInvoker isn't known; tests will use msg.sender equivalence by calling as account (this contract)
    }

    // single public function with inputs to test both openMakeFor and openTakeFor
    function run(bool make, uint256 amountRaw) public payable {
        require(amountRaw <= type(uint128).max, "amount too large");
        // represent amount as UFixed18 by calling UFixed18.wrap is not allowed; instead we pass through C's external functions which accept UFixed18 type aliases as uint256
        uint256 amount = amountRaw;

        // Observe closed before
        bool closedBefore = c.closed();

        // We will attempt the call and catch whether it reverted.
        bool reverted = false;
        // We also attempt to read latestVersion and price at that version to compute expected non-negative fee if call succeeds
        uint256 latestVer = c.latestVersion();
        // If latestVer == 0, some operations (openMake/openTake) may revert due to nonZeroVersionInvariant; that's OK.

        // Make the modifying call as top-level statement
        if (make) {
            // attempt openMakeFor(this, amount)
            try c.openMakeFor(address(this), UFixed18(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(address(this), UFixed18(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After call, closed must remain same unless updateClosed was called (not in this test), so assert equality
        bool closedAfter = c.closed();

        // If the call succeeded (not reverted) then the contract must have charged a non-negative position fee.
        // We cannot observe fees directly, but we can observe that maintenance/account views are defined and not revert.
        // We'll assert: if call succeeded then closed unchanged and closedAfter == closedBefore.
        // Also ensure reverted implies no change to closed (closedAfter == closedBefore) as well.

        assert(closedAfter == closedBefore);
    }

    // receive to accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // action: 0=openMakeFor,1=openTakeFor,2=closeMakeFor,3=closeTakeFor
    // amount is passed as uint256 which maps to the UFixed18 typedef expected by C's ABI
    function run(uint8 action, uint256 amount) public payable {
        require(action <= 3, "bad action");

        bool closedBefore = c.closed();

        bool reverted;
        if (action == 0) {
            // openMakeFor
            try c.openMakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            // openTakeFor
            try c.openTakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 2) {
            // closeMakeFor
            try c.closeMakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // closeTakeFor
            try c.closeTakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        bool closedAfter = c.closed();

        // General invariant: these per-account actions must not flip the product closed flag
        assert(closedAfter == closedBefore);
    }

    receive() external payable {}
}

