contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that invoking openMakeFor or openTakeFor either reverts or results in
    // a non-negative position fee being charged (observed via collateral fees change)
    // and does not flip the product's closed() flag from false to true.
    // We take inputs to choose which action and amounts.
    function run(bool useMake, address account, uint256 amountRaw) public payable {
        require(account != address(0));
        // Normalize amount into a UFixed18 representation by treating raw as integer units
        // The contract expects UFixed18 but takes it as a type alias; passing uint256 compiles.
        uint256 amount = amountRaw;

        // Read preconditions/observations
        bool closedBefore = c.closed();
        // read collateral fees for this contract (the test contract) BEFORE acting
        // collateral.fees is not directly available here; but controller().collateral().fees is accessible via c.controller().collateral().fees(address)
        // However we must only call public/external functions on c. Use controller() getter then collateral() then fees().
        IController controller = c.controller();
        ICollateral collateral = controller.collateral();
        // Read fees before
        UFixed18 feesBefore = collateral.fees(address(this));

        bool reverted;
        // Perform the deciding call; must be top-level statements for state-changing calls.
        if (useMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read fees after and closed flag after
        UFixed18 feesAfter = collateral.fees(address(this));
        bool closedAfter = c.closed();

        // The rule:
        // - If the call succeeded (not reverted) then feesAfter must be >= feesBefore (position fees charged are represented as added fees to the caller),
        //   and closed flag must not have transitioned from false to true.
        // - If the call reverted, nothing required about fees but closed must remain unchanged (revert should not flip closed).

        if (!reverted) {
            // feesAfter >= feesBefore
            assert(feesAfter.gte(feesBefore) && (closedBefore == closedAfter || (!closedBefore && !closedAfter)));
        } else {
            // if reverted, closed flag must be unchanged
            assert(closedBefore == closedAfter);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check.
    // Inputs:
    // - useMake: choose openMakeFor (true) or openTakeFor (false)
    // - account: target account for the call
    // - amount: raw uint256 amount passed as UFixed18 (no wrapping available here; pass as uint256)
    function run(bool useMake, address account, uint256 amount) public payable {
        require(account != address(0));

        // Observe closed flag and caller's collateral fees before the operation
        bool closedBefore = c.closed();
        IController controller = c.controller();
        ICollateral collateral = controller.collateral();
        UFixed18 feesBefore = collateral.fees(address(this));

        // Perform the deciding call as a top-level statement and capture revert via try/catch
        bool reverted;
        if (useMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read post-state observables
        bool closedAfter = c.closed();
        UFixed18 feesAfter = collateral.fees(address(this));

        // Single assert stating the general rule: if the call did not revert then closed must not have flipped false->true
