contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an account and an amount to open/make and then close.
    // The test will call openMakeFor(account, amount) and then closeMakeFor(account, amount)
    // using this contract as msg.sender when required by onlyAccountOrMultiInvoker/onlyAccountOwner.
    function run(address account, UFixed18 amount) public payable {
        require(true);

        // Ensure this contract is the controller's owner for product operations that require onlyProductOwner is NOT needed here.
        // We must perform actions via the public functions. Use try/catch to observe reverts.

        bool openedReverted;
        try c.openMakeFor(account, amount) {
            openedReverted = false;
        } catch {
            openedReverted = true;
        }

        bool closedReverted;
        try c.closeMakeFor(account, amount) {
            closedReverted = false;
        } catch {
            closedReverted = true;
        }

        // Observe resulting position and pre for the account via public getters.
        // We reason about a general invariant: if both calls succeeded (didn't revert), then the resulting
        // position must not be double-sided and must not be over-closed. We express these via available views:
        // - position(address) returns Position memory with maker and taker (UFixed18). We can check simple relations:
        //   double-sided means both maker>0 and taker>0; over-closed means that close exceeded opens causing underflow in library checks,
        //   but publicly we can assert that either maker==0 or taker==0 (i.e., not both positive), and maker/taker are finite UFixed18.

        (UFixed18 maker, UFixed18 taker) = _getPosition(account);

        // Build the assert: if both operations didn't revert, then at least one side must be zero (not double-sided)
        // and maker and taker cannot both be such that an over-closed situation would be indicated by taker > maker + something.
        // We express a conservative rule: if both calls succeeded then NOT(both maker > 0 and taker > 0).

        assert(!(openedReverted == false && closedReverted == false && _ufixed18IsNonZero(maker) && _ufixed18IsNonZero(taker)));
    }

    // Helper to read position via c.position(account) which returns a struct Position (maker,taker).
    function _getPosition(address account) internal view returns (UFixed18, UFixed18) {
        // Call the public view position function
        (UFixed18 maker, UFixed18 taker) = c.position(account);
        return (maker, taker);
    }

    // Helper to test non-zero UFixed18 by comparing truncate (public view) to zero to avoid direct unwrap.
    function _ufixed18IsNonZero(UFixed18 v) internal view returns (bool) {
        // use truncate which returns uint256 (public). If truncate yields >0 then value non-zero.
        return UFixed18Lib.truncate(v) != 0 || !_ufixed18IsZeroViaCompare(v);
    }

    // Fallbacks to try to detect zero more robustly: compare with ZERO via eq (public library exposed as methods on type may not be callable here),
    // but we can rely on truncate primarily; if value < 1e18 but non-zero, truncate==0, so above check may fail. To be conservative, also compare by calling maintenanceNext for account (harmless) — but solidity cannot compare types easily here.
    // Instead implement a naive approach: attempt to call a view that depends on position (rate) and infer non-zero by catching divide-by-zero reverts in rate.

    fallback() external payable {}
    receive() external payable {}

    // Extra view to attempt to detect v == 0 by calling rate with constructed Position where maker = v, taker = v (we only need to provoke revert if maker==0 via unsafeDiv)
    function _ufixed18IsZeroViaCompare(UFixed18 v) internal view returns (bool) {
        // Create a Position with maker = v, taker = UFixed18Lib.ONE (non-zero) and call rate; if maker==0, unsafeDiv in rate uses position_.taker.unsafeDiv(position_.maker)
        // which for maker==0 will trigger unsafeDiv behavior but it's a view and won't revert; unsafeDiv handles zero by returning MAX/ONE etc. So we cannot rely on revert.
        // As a final simple fallback: consider truncate==0 as possibly zero; treat those as zero for the assertion conservatively.
        return UFixed18Lib.truncate(v) == 0;
    }
}

