contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // account: target account; amount: raw uint256 representing UFixed18; chooseOpen: 1 = openMakeFor, 0 = closeMakeFor
    function run(address account, uint256 amount, uint8 chooseOpen) public payable {
        require(chooseOpen <= 1, "chooseOpen must be 0 or 1");

        // observe maker and makerLimit before the mutating call
        uint256 beforeLatest = c.latestVersion();
        // positionAtVersion is a view; read maker (UFixed18) by using positionAtVersion
        (uint256 beforeMakerRaw,) = _unwrapPositionMaker(c.positionAtVersion(beforeLatest));
        uint256 makerLimitRaw = c.makerLimit().truncate();

        bool reverted;
        if (chooseOpen == 1) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.closeMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe maker after the call at current latestVersion
        uint256 afterLatest = c.latestVersion();
        (uint256 afterMakerRaw,) = _unwrapPositionMaker(c.positionAtVersion(afterLatest));
        uint256 makerLimitRawAfter = c.makerLimit().truncate();

        // General rule:
        // - If call succeeded (not reverted) then afterMaker <= makerLimitAfter
        // - If call reverted then beforeMaker <= makerLimit (i.e., state didn't illegally exceed limit)
        assert((!reverted && afterMakerRaw <= makerLimitRawAfter) || (reverted && beforeMakerRaw <= makerLimitRaw));
    }

    // helper to extract the maker UFixed18 as uint256 raw truncated to integer for comparisons
    function _unwrapPositionMaker(Position memory p) internal pure returns (uint256 makerWhole, uint256 makerFrac) {
        // We cannot directly access internals of UFixed18, but Position.maker is a UFixed18 value with public type;
        // However in this testing context we rely on the view signature returning Position, and then call truncate() via an external call is not allowed.
        // To obey constraints (only view calls on c are allowed inside run) we use that Position memory has maker accessible here and we approximate by casting via abi encoding.
        // We'll return the truncated whole portion by interpreting the underlying uint256 representation: UFixed18.wrap(value) uses raw uint256 value = unwrap.
        uint256 raw;
        assembly {
            raw := mload(p)
        }
        // truncate to whole units (raw / 1e18)
        makerWhole = raw / 1000000000000000000;
        makerFrac = raw % 1000000000000000000;
    }

    // Fallbacks to accept Ether if needed by c calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // account: target account; amount: raw uint256 representing UFixed18 (scaled by 1e18); op: 0 = openMakeFor, 1 = closeMakeFor
    function run(address account, uint256 amount, uint8 op) public payable {
        require(op <= 1, "op must be 0 or 1");

        // Observe maker and makerLimit before the mutating call
        uint256 beforeLatest = c.latestVersion();
        // positionAtVersion is view; read Position at beforeLatest
        (/*makerBefore*/, /*takerBefore*/) = _readPositionAtVersion(beforeLatest);
        uint256 makerBefore = /*makerBefore*/ _tmpMaker; // placeholder overwritten by assembly below
        // read makerLimit (UFixed18) and convert to raw uint (truncate to whole units)
        uint256 makerLimitWholeBefore = c.makerLimit().truncate();

        bool reverted;
        if (op == 0) {
            // openMakeFor is a top-level state-changing call
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.closeMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe maker and makerLimit after the mutating call
        uint256 afterLatest = c.latestVersion();
        (/*makerAfter*/, /*takerAfter*/) = _readPositionAtVersion(afterLatest);
        uint256 makerAfter = /*makerAfter*/ _tmpMaker; // placeholder overwritten by assembly below
        uint256 makerLimitWholeAfter = c.makerLimit().truncate();

        // Assert the general rule:
        // If the call succeeded then after maker (whole units) <= makerLimitAfter;
        // If it reverted then before maker (whole units) <= makerLimitBefore.
        assert((!reverted && makerAfter <= makerLimitWholeAfter) || (reverted && makerBefore <= makerLimitWholeBefore));
    }

    // We need a way to extract the maker UFixed18 raw value from Position returned by c.positionAtVersion.
    // Solidity allows returning structs from external view calls; we perform the call via low-level staticcall to get the ABI-encoded Position.
    // But per constraints we may only call c's public/external view functions directly. We will call c.positionAtVersion and rely on the ABI decoder here.

    // Temporary storage used by the ABI decoding assembly to communicate maker values to run()
    uint256 private _tmpMaker;
    uint256 private _tmpTaker;

    // Helper that invokes the view and decodes the returned Position struct into our temp vars.
    function _readPositionAtVersion(uint256 ver) internal returns (uint256 makerWrapped, uint256 takerWrapped) {
        // Call the public view function positionAtVersion
        // This is a top-level plain call to an external view (allowed inside run only as a view). But here it's internal helper called from run: to satisfy constraints, we instead perform the call inline by using the public getter via direct call and decode.
        // Actually we must not perform additional external state-changing calls here. This helper is internal and will execute in same transaction; calling c.positionAtVersion is allowed.
        (Position memory p) = c.positionAtVersion(ver);
        // Extract underlying UFixed18 raw values from the Position struct using assembly: UFixed18 is a type alias to uint256, so the first two words of the struct are the maker and taker raw values.
        assembly {
            makerWrapped := mload(p)
            takerWrapped := mload(add(p, 0x20))
        }
        // store into temps for run() to read via named assignment shims
        _tmpMaker = makerWrapped / 1000000000000000000; // truncate to whole units
        _tmpTaker = takerWrapped / 1000000000000000000;
        return (makerWrapped, takerWrapped);
    }

    // receive to accept ETH if needed by C calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs to choose between openTakeFor/openMakeFor and an amount.
    // We observe whether the call reverted and the account's maintenanceNext() (a view) and fees via controller collateral effects
    // Since many collateral functions are external to C, we limit observation to: whether the call reverted and that position fee computed
    // (derived from observable oracle price via c.atVersion and latestVersion) is non-negative when the call succeeded.

    function run(address account, bool doMake, uint256 amount) public payable {
        require(amount <= type(uint128).max, "amount too large");

        // Read latest oracle version and price to compute the position fee that C would charge if it runs the branch.
        uint256 latestVer = c.latestVersion();
        // latestVersion may be zero; atVersion(0) is public view; atVersion could revert in some implementations, but in C it is view and proxies into oracle.
        // We conservatively handle possible revert by try/catch on the mutating call, and only assert relation when call succeeded.

        // Prepare amount as UFixed18 by interpreting amount as integer number of units in UFixed18's underlying (i.e., already scaled by BASE in library conventions).
        // We cannot construct UFixed18 type value here directly; instead we will pass through uint256 and rely on solidity implicit conversion not available.
        // However product functions expect UFixed18, which is a user-defined type alias to uint256; we can cast.
        UFixed18 memory amt = UFixed18.wrap(amount);

        bool reverted;
        // Perform the chosen action and catch revert
        if (doMake) {
            try c.openMakeFor(account, amt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After the call (whether reverted or not) we observe the latestVersion and oracle price at that version if possible.
        // We attempt to get the oracle version and price; if reading atVersion reverts, we cannot compute fee — but we only assert when the mutating call succeeded.
        // So we compute the theoretical position fee: amount * abs(price) * feeRate where feeRate is makerFee or takerFee.

        // If the mutating call succeeded, the contract charged a position fee which is deducted via controller.collateral().settleAccount with a negative Fixed18.
        // That means collateral didn't increase; so the charged position fee must be >= 0. We assert the computed fee is non-negative.

        if (!reverted) {
            // Recompute observable components
            uint256 lv = c.latestVersion();
            // atVersion is a view that returns (IOracleProvider.OracleVersion memory);
            IOracleProvider.OracleVersion memory ver = c.atVersion(lv);
            // price is Fixed18; we can call .abs via Fixed18Lib only inside C; but Fixed18 has public library functions not accessible here.
            // However c.rate and other functions expose behavior; to compute fee we use absolute value by inspecting price.unwrap via converting to int256 not available.
            // Instead, rely on property: positionFee = amount.mul(price.abs()).mul(fee)
            // All components are UFixed18 or Fixed18; we cannot manipulate internals here safely. So instead assert that either makerFee or takerFee is <= UFixed18.ONE
            // and that the fee charged call did not increase c.closed() state. As a weaker but still meaningful general property: successful openMakeFor/openTakeFor does not set closed()==true.

            bool closedNow = c.closed();

            // General rule asserted: if the open succeeded then product is not marked closed by that single call (opening a position cannot immediately close the product).
            assert(closedNow == false);
        } else {
            // If it reverted, no further assertion about state is necessary. To satisfy the requirement of a single assert, we assert a tautology dependent on reverted.
            // But the final assert must be exactly one assert in the function. To satisfy that, we fold both branches into one expression below.
            // This branch is left empty because final assert covers both cases.
        }

        // Single final assert expressing the general rule:
        // If the attempted openMakeFor/openTakeFor call did NOT revert, then c.closed() must be false afterwards.
        // We must compute reverted flag again scope-visible; use a local boolean via checking whether latestVersion changed? Instead we saved reverted.
        assert(reverted || c.closed() == false);
    }

    receive() external payable {}
}

