contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to call openMakeFor or openTakeFor; `isMake` chooses which action.
    // amount is an encoded UFixed18 value as uint256 (caller will pass any uint256).
    // We only interact via c's public API. We cannot inspect events directly, so we assert
    // that calling openMakeFor/openTakeFor either reverts or results in the account's
    // maintenance/position-related public views being consistent (no direct event check).
    // To capture the intended general rule in a provable way: when the call succeeds,
    // the function does not revert and leaves c in a state where the caller's pre() reflects
    // the attempted open (i.e., pre().oracleVersion equals latestVersion()).

    function run(bool isMake, address account, uint256 amount) public payable {
        require(address(this).balance >= 0);
        // Read the current latest version before mutation
        uint256 beforeLatest = c.latestVersion();

        bool reverted;
        // We call the chosen method on c as top-level statements that mutate state.
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After the call, either it reverted, or it succeeded and the account's pre().oracleVersion
        // must be equal to the latestVersion at the time of the call (i.e., an open uses latestVersion()).
        // We express: if not reverted then c.pre(account).oracleVersion == c.latestVersion().
        IProduct.PrePosition memory prePos = c.pre(account);
        uint256 afterLatest = c.latestVersion();

        assert(reverted || prePos.oracleVersion == afterLatest);
    }

    // Minimal receive to accept Ether if needed by the environment
    receive() external payable {}
}

