contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Choose action (make/take), target account, and raw amount (UFixed18 encoded as uint256)
    function run(bool isMake, address account, uint256 amount) public payable {
        require(account != address(0), "account-zero");

        // read latest oracle version before call
        uint256 beforeLatest = c.latestVersion();

        bool reverted;

        // perform the mutating call as a top-level statement (try-catch allowed)
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe public state after the call
        PrePosition memory acctPre = c.pre(account);
        PrePosition memory prodPre = c.pre();
        uint256 afterLatest = c.latestVersion();

        // General rule:
        // If the call did not revert then (1) the product's latestVersion did not decrease,
        // (2) the account's pre.oracleVersion equals the product pre.oracleVersion (both set to latestVersion),
        // and (3) the side that was opened has at least the requested amount in the account's pre.openPosition for that side.
        // We express (3) by requiring the appropriate field to be >= amount.
        if (!reverted) {
            // latestVersion must be non-decreasing
            bool nonDecreasing = afterLatest >= beforeLatest;

            // both product pre and account pre should reference the same oracleVersion
            bool samePreVersion = acctPre.oracleVersion == prodPre.oracleVersion && acctPre.oracleVersion == afterLatest;

            // check opened side has amount >= requested
            bool sideOk;
            if (isMake) {
                sideOk = UFixed18.unwrap(acctPre.openPosition.maker) >= amount;
            } else {
                sideOk = UFixed18.unwrap(acctPre.openPosition.taker) >= amount;
            }

            assert(nonDecreasing && samePreVersion && sideOk);
        } else {
            // If it reverted we place no further constraint besides reaching the assert.
            assert(reverted || true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // isMake: true -> openMakeFor, false -> openTakeFor
    // account: target account for the action
    // amount: UFixed18 raw uint256 value
    function run(bool isMake, address account, uint256 amount) public payable {
        require(account != address(0), "account-zero");

        // read product latestVersion before call (view)
        uint256 beforeLatest = c.latestVersion();

        bool callReverted;

        // perform the mutating call as a top-level statement (no nesting)
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // read observable public state after the call
        uint256 afterLatest = c.latestVersion();
        (uint256 acctPreOracleVersion, , ) = abi.decode(abi.encode(c.pre(account)), (uint256, (UFixed18), (UFixed18)));
        (uint256 prodPreOracleVersion, , ) = abi.decode(abi.encode(c.pre()), (uint256, (UFixed18), (UFixed18)));

        // Also read the account pre.openPosition amounts via the public pre(account) getter again
        PrePosition memory acctPre = c.pre(account);

        // Single assert expressing the general rule:
        // If call succeeded (not reverted) then:
        //  - product.latestVersion did not decrease
        //  - account pre.oracleVersion equals product pre.oracleVersion equals latestVersion
        //  - the opened side in account pre.openPosition has at least 'amount'
        // Otherwise (reverted) no further property is required (assert still must be reachable).
        assert(
            callReverted
            || (
                afterLatest >= beforeLatest
                && acctPre.oracleVersion == prodPreOracleVersion
                && acctPre.oracleVersion == afterLatest
                && (
                    (isMake && UFixed18.unwrap(acctPre.openPosition.maker) >= amount)
                    || (!isMake && UFixed18.unwrap(acctPre.openPosition.taker) >= amount)
                )
            )
        );
    }

    receive() external payable {}
}

