        // observe latestVersion before the call
        uint256 beforeLatest = c.latestVersion();

        bool callReverted;

        // perform the mutating call as a top-level statement
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // observe public state after the call
        uint256 afterLatest = c.latestVersion();
        // read product pre() and account pre()
        (uint256 prodPreOracleVersion, UFixed18 prodPreOpenMaker, UFixed18 prodPreOpenTaker) = _unpackPre(c.pre());
        (uint256 acctPreOracleVersion, UFixed18 acctPreOpenMaker, UFixed18 acctPreOpenTaker) = _unpackPre(c.pre(account));

        // Single assert stating the general rule
        assert(
            callReverted
            || (
                // latestVersion did not decrease
                afterLatest >= beforeLatest
                // account pre.oracleVersion equals product pre.oracleVersion
                && acctPreOracleVersion == prodPreOracleVersion
                // account pre.oracleVersion equals the product latestVersion
                && acctPreOracleVersion == afterLatest
                // and the requested side's pre.openPosition amount is at least the requested amount
                && (
                    (isMake && UFixed18.unwrap(acctPreOpenMaker) >= amount)
                    || (!isMake && UFixed18.unwrap(acctPreOpenTaker) >= amount)
                )
            )
        );
    }

    receive() external payable {}

    // helper to unpack PrePosition returned by c.pre() view (allowed: view call used only in helpers inside the same contract)
    function _unpackPre(PrePosition memory p) private pure returns (uint256, UFixed18, UFixed18) {
        return (p.oracleVersion, p.openPosition.maker, p.openPosition.taker);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will try to open a take or make and check that the position fee computed from
    // current oracle price and fee parameters is non-negative and that latestVersion() does not decrease.
    // Since we cannot observe internal collateral accounting, we use address(c).balance as a proxy:
    // when positionFee is zero, the test assumes no Ether transfer to/from c (balance unchanged).
    function run(bool openTake, uint256 amountRaw) public payable {
        require(amountRaw > 0, "amount must be >0");

        // read some before-values
        uint256 beforeLatest = c.latestVersion();
        address productAddr = address(c);
        uint256 beforeBal = productAddr.balance;

        // compute an amount as UFixed18: the contract exposes functions taking UFixed18, but we cannot construct that type here directly.
        // Instead we will call openTakeFor/openMakeFor with amount represented as UFixed18 via casting to uint256 (the ABI accepts it).
        uint256 amount = amountRaw;

        bool reverted = false;
        // perform the mutating call depending on openTake flag
        if (openTake) {
            try c.openTakeFor(address(this), UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openMakeFor(address(this), UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        uint256 afterLatest = c.latestVersion();
        uint256 afterBal = productAddr.balance;

        // We assert a general rule:
        // - latestVersion never decreases
        // - position fee (as observable) is non-negative: we can't directly read it, but if the call succeeded
        //   then no revert implies invariants held; and we require that contract balance did not increase (product shouldn't receive Ether in these flows)
        // - if balance unchanged then we assume position fee was zero (caller collateral settlement would have transferred internal accounting only)

        // Compose the assertion combining these observable facts.
        assert(afterLatest >= beforeLatest && (reverted || afterBal >= beforeBal));
    }

    // To satisfy compiler for using UFixed18 in calls, declare a minimal wrapper type here to match ABI packing.
    // Note: this declaration is only to allow compilation of the test; it does not redeclare C or other contracts.
    // The ABI uses the underlying uint256 representation for UFixed18.
    type UFixed18 is uint256;

    receive() external payable {}
}

